create table if not exists geo_audits (id uuid primary key default gen_random_uuid(),project_id uuid not null references projects(id) on delete cascade,url text not null,status text not null default 'pending',score integer,summary jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),completed_at timestamptz);create table if not exists geo_audit_issues (id uuid primary key default gen_random_uuid(),audit_id uuid not null references geo_audits(id) on delete cascade,category text not null,severity text not null,title text not null,detail text,action text,created_at timestamptz not null default now());alter table geo_audits enable row level security;alter table geo_audit_issues enable row level security;create policy "owners read audits" on geo_audits for select using(exists(select 1 from projects p where p.id=project_id and p.owner_id=auth.uid()));create policy "owners read audit issues" on geo_audit_issues for select using(exists(select 1 from geo_audits a join projects p on p.id=a.project_id where a.id=audit_id and p.owner_id=auth.uid()));